function validate([arr, queries]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 30000) return 'arr needs 1 to 30000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of arr is an integer from 1 to 10^9.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 30000) return 'queries needs 1 to 30000 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [left, right].';
    const [left, right] = query;
    if (!Number.isInteger(left) || !Number.isInteger(right) || left < 0 || left > right || right >= arr.length) return 'Each query needs 0 <= left <= right < arr.length.';
  }
  return null;
}

