function xorQueries(arr, queries) {
  const prefix = new Array(arr.length + 1).fill(0);
  for (let i = 0; i < arr.length; i++) {
    prefix[i + 1] = prefix[i] ^ arr[i];
  }

  const answer = [];
  for (const [left, right] of queries) {
    answer.push(prefix[right + 1] ^ prefix[left]);
  }
  return answer;
}

