function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const q = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 1e9 : (rand() < 0.5 ? 7 : 1e9);
  const arr = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const queries = Array.from({ length: q }, () => {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    return [Math.min(a, b), Math.max(a, b)];
  });
  return [arr, queries];
}
